finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd45: rowUpdateCachedGeneric for [R8, R9) (mls 4, rowLog 5), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd45(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0x9e3779b100000000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $5, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $5, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $31, R10
	CMOVLEQ rowMask31<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch45: rowFindBestMatch (noDict, mls 4, rowLog 5) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch45(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd45(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd45(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $5, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $31, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVL      R10, CX
	RORL      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $31, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $31, CX
	CMOVLEQ rowMask31<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow45(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 4,
// rowLog 5: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow45(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch45(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd46: rowUpdateCachedGeneric for [R8, R9) (mls 4, rowLog 6), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd46(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0x9e3779b100000000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $6, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 32(BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $6, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $63, R10
	CMOVLEQ rowMask63<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch46: rowFindBestMatch (noDict, mls 4, rowLog 6) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch46(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd46(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd46(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $6, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $63, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVOU     32(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $32, DX
	ORQ       DX, R11
	MOVOU     48(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $48, DX
	ORQ       DX, R11
	MOVL      R10, CX
	RORQ      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $63, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $63, CX
	CMOVLEQ rowMask63<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow46(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 4,
// rowLog 6: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow46(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch46(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0x9e3779b100000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd54: rowUpdateCachedGeneric for [R8, R9) (mls 5, rowLog 4), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd54(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbb000000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $4, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $4, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $15, R10
	CMOVLEQ rowMask15<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch54: rowFindBestMatch (noDict, mls 5, rowLog 4) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch54(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd54(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd54(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $4, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $15, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVL      R10, CX
	RORW      CX, R11
	MOVWLZX   R11, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $15, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $15, CX
	CMOVLEQ rowMask15<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow54(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 4: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow54(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch54(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd55: rowUpdateCachedGeneric for [R8, R9) (mls 5, rowLog 5), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd55(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbb000000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $5, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $5, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $31, R10
	CMOVLEQ rowMask31<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch55: rowFindBestMatch (noDict, mls 5, rowLog 5) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch55(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd55(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd55(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $5, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $31, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVL      R10, CX
	RORL      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $31, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $31, CX
	CMOVLEQ rowMask31<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow55(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 5: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow55(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch55(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd56: rowUpdateCachedGeneric for [R8, R9) (mls 5, rowLog 6), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd56(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbb000000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $6, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 32(BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $6, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $63, R10
	CMOVLEQ rowMask63<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch56: rowFindBestMatch (noDict, mls 5, rowLog 6) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch56(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd56(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd56(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $6, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $63, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVOU     32(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $32, DX
	ORQ       DX, R11
	MOVOU     48(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $48, DX
	ORQ       DX, R11
	MOVL      R10, CX
	RORQ      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $63, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $63, CX
	CMOVLEQ rowMask63<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow56(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 5,
// rowLog 6: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow56(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch56(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbb000000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd64: rowUpdateCachedGeneric for [R8, R9) (mls 6, rowLog 4), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd64(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbf9b0000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $4, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $4, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $15, R10
	CMOVLEQ rowMask15<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch64: rowFindBestMatch (noDict, mls 6, rowLog 4) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch64(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd64(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd64(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $4, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $15, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVL      R10, CX
	RORW      CX, R11
	MOVWLZX   R11, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $15, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $15, CX
	CMOVLEQ rowMask15<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow64(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 4: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow64(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch64(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $4, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd65: rowUpdateCachedGeneric for [R8, R9) (mls 6, rowLog 5), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd65(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbf9b0000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $5, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $5, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $31, R10
	CMOVLEQ rowMask31<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch65: rowFindBestMatch (noDict, mls 6, rowLog 5) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch65(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd65(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd65(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $5, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $31, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVL      R10, CX
	RORL      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $31, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $31, CX
	CMOVLEQ rowMask31<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow65(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 5: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow65(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch65(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $5, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

// rowUpd66: rowUpdateCachedGeneric for [R8, R9) (mls 6, rowLog 6), prefetching
// each new hash's row. R15 = p. Clobbers AX, BX, CX, DX, DI, SI, R8, R10-R14.
TEXT ·rowUpd66(SB), NOSPLIT, $0-0
	CMPL R8, R9
	JAE  done
	MOVQ P_HASHTABLE, AX
	MOVQ P_TAGTABLE, BX
	MOVQ P_CACHE, DX
	MOVQ P_B, SI
	MOVL P_BASEIDX, R10
	SUBQ R10, SI
	MOVQ $0xcf1bbcdcbf9b0000, R11
	MOVQ P_SALT, R12
	MOVQ P_HSHIFT, CX

loop:
	MOVL  R8, R10
	MOVQ  8(SI)(R10*1), DI
	IMULQ R11, DI
	XORQ  R12, DI
	SHRQ  CX, DI               // newHash
	MOVL  DI, R13
	SHRL  $8, R13
	SHLL  $6, R13
	PREFETCHT0 (AX)(R13*4)
	PREFETCHT0 64(AX)(R13*4)
	PREFETCHT0 (BX)(R13*1)
	PREFETCHT0 32(BX)(R13*1)
	ANDL  $7, R10
	MOVL  (DX)(R10*4), R14     // hash
	MOVL  DI, (DX)(R10*4)
	MOVL  R14, R13
	SHRL  $8, R13
	SHLL  $6, R13           // relRow
	MOVBLZX (BX)(R13*1), R10
	DECL  R10
	ANDL  $63, R10
	CMOVLEQ rowMask63<>(SB), R10 // head 0 wraps to rowMask (C: cmove)
	MOVB  R10, (BX)(R13*1)
	ADDQ  R10, R13
	MOVB  R14, (BX)(R13*1)
	MOVL  R8, (AX)(R13*4)
	INCL  R8
	CMPL  R8, R9
	JB    loop

done:
	RET

// rowSearch66: rowFindBestMatch (noDict, mls 6, rowLog 6) at DI = ip, R15 = p.
// Returns AX = ml (below 4: none; -1: a table entry at or after ip, impossible),
// BX = offBase. Clobbers everything but R15.
TEXT ·rowSearch66(SB), NOSPLIT, $280-0
	MOVQ DI, S_IP
	MOVQ P_B, SI
	MOVL P_BASEIDX, CX
	ADDL DI, CX
	MOVL CX, S_CURR

	// lowLimit = isDictionary ? lowestValid : withinMaxDistance
	MOVL P_LOWEST, DX
	MOVL CX, BX
	SUBL DX, BX
	CMPL BX, P_MAXDIST
	JLS  lowok
	MOVL CX, DX
	SUBL P_MAXDIST, DX

lowok:
	CMPL P_ISDICT, $0
	JEQ  lowset
	MOVL P_LOWEST, DX

lowset:
	MOVL DX, S_LOWLIM
	CMPL P_SKIP, $0
	JNE  skipping

	// ZSTD_row_update_internal(useCache = 1)
	MOVQ P_NEXT, AX
	MOVL (AX), R8
	MOVL S_CURR, R9
	MOVL R9, AX
	SUBL R8, AX
	CMPL AX, $384
	JLS  upd
	MOVL R8, R9
	ADDL $96, R9
	CALL ·rowUpd66(SB)
	// ZSTD_row_fillHashCache from target - 32 (8 entries, all before ip+1)
	MOVQ P_B, SI
	MOVQ P_CACHE, DX
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL $8, BX

fill:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECL BX
	JNE  fill
	MOVL S_CURR, R8
	SUBL $32, R8
	MOVL S_CURR, R9

upd:
	CALL ·rowUpd66(SB)
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

	// hash = ZSTD_row_nextCachedHash(curr)
	MOVQ P_B, SI
	MOVQ S_IP, DI
	MOVQ 8(SI)(DI*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVQ P_CACHE, DX
	MOVL S_CURR, AX
	ANDL $7, AX
	MOVL (DX)(AX*4), BX
	MOVL R10, (DX)(AX*4)
	JMP  havehash

skipping:
	MOVQ (SI)(DI*1), BX
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, BX
	XORQ P_SALT, BX
	MOVQ P_HSHIFT, CX
	SHRQ CX, BX
	MOVQ P_NEXT, AX
	MOVL S_CURR, CX
	MOVL CX, (AX)

havehash:
	MOVQ P_ENTROPY, AX
	ADDL BX, (AX)           // collect salt entropy
	MOVL BX, DX
	ANDL $0xFF, DX
	MOVL DX, S_TAG
	SHRL $8, BX
	SHLL $6, BX          // relRow
	MOVQ P_HASHTABLE, AX
	LEAQ (AX)(BX*4), AX     // row
	ADDQ P_TAGTABLE, BX     // tagRow
	MOVL P_BASEIDX, R9
	NEGQ R9
	ADDQ SI, R9             // b - baseIdx: an index addresses b directly
	MOVL S_CURR, DI         // curr (ip is reloaded after the gather)
	MOVL P_ATTEMPTS, R14
	MOVBLZX (BX), R10
	ANDL $63, R10      // headGrouped

	// matches: tags equal to tag, rotated right by headGrouped (C: ZSTD_row_getSSEMask)
	MOVQ      DX, X0
	PUNPCKLBW X0, X0
	PUNPCKLWL X0, X0
	PSHUFL    $0, X0, X0
	MOVOU     (BX), X1
	PCMPEQB   X0, X1
	PMOVMSKB  X1, R11
	MOVOU     16(BX), X2
	PCMPEQB   X0, X2
	PMOVMSKB  X2, DX
	SHLL      $16, DX
	ORL       DX, R11
	MOVOU     32(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $32, DX
	ORQ       DX, R11
	MOVOU     48(BX), X3
	PCMPEQB   X0, X3
	PMOVMSKB  X3, DX
	SHLQ      $48, DX
	ORQ       DX, R11
	MOVL      R10, CX
	RORQ      CX, R11
	MOVL      S_LOWLIM, R12
	XORL      R13, R13
	JMP       gnext             // nbAttempts >= 1

gather:
	XORL  CX, CX            // BSF keeps its destination on a zero input, so it reads CX: break the chain
	BSFQ  R11, CX
	LEAQ  -1(R11), DX
	ANDQ  DX, R11
	ADDL  R10, CX
	ANDL  $63, CX
	JEQ   gnext             // the head entry is not a candidate
	MOVL  (AX)(CX*4), DX
	CMPL  DX, R12
	JB    insert            // below lowLimit: stop
	// Bounds: lowLimit <= DX < curr, and lowLimit >= baseIdx (rowAsmSetup
	// checks lowestValid >= baseIdx, and lazyRowRun lowestValid <= curr, so
	// curr - lowestValid does not wrap and curr - maxDistance is used only
	// when it is above lowestValid). So R9 + DX lies in b[0:ip], and the
	// compare and count below read only b[DX-baseIdx:] up to the
	// iLimit - ip bytes that b[ip:] holds. Only buffered candidates are
	// read, and every one passed this check, so the compare loop needs none.
	CMPL  DX, DI
	JAE   bad
	PREFETCHT0 (R9)(DX*1)
	MOVL  DX, 0(SP)(R13*4)
	INCL  R13
	DECL  R14
	JEQ   insert

gnext:
	TESTQ R11, R11
	JNE   gather

insert:
	MOVBLZX (BX), CX
	DECL    CX
	ANDL    $63, CX
	CMOVLEQ rowMask63<>(SB), CX
	MOVB    CX, (BX)
	MOVL    S_TAG, DX
	MOVB    DX, (BX)(CX*1)
	MOVQ    P_NEXT, R12
	MOVL    (R12), DX
	MOVL    DX, (AX)(CX*4)
	INCL    (R12)           // nextToUpdate++

	MOVL $3, R10
	XORL R11, R11
	XORL R12, R12
	MOVQ S_IP, DI
	LEAQ (SI)(DI*1), BX
	MOVQ P_ILIMIT, R8
	SUBQ DI, R8             // iLimit - ip

cmp:
	CMPQ R12, R13
	JAE  done
	MOVL 0(SP)(R12*4), DX
	INCQ R12
	LEAQ (R9)(DX*1), AX
	MOVL -3(AX)(R10*1), R14
	CMPL R14, -3(BX)(R10*1)
	JNE  cmp
	// count (as fastCount): 8 bytes, then 32 per step with AVX2
	XORL R14, R14
	CMPQ R8, $8
	JB   cnttail
	MOVQ (AX), CX
	XORQ (BX), CX
	JNE  cntdiff
	MOVL $8, R14
	CMPB ·useAVX2(SB), $0
	JEQ  cnt8

cnt32:
	LEAQ 32(R14), CX
	CMPQ CX, R8
	JA   cnt32end
	VMOVDQU   (AX)(R14*1), Y0
	VPCMPEQB  (BX)(R14*1), Y0, Y0
	VPMOVMSKB Y0, CX
	INCL      CX
	JNE       cnt32diff
	ADDQ      $32, R14
	JMP       cnt32

cnt32diff:
	VZEROUPPER
	BSFL CX, CX
	ADDQ CX, R14
	JMP  cntdone

cnt32end:
	VZEROUPPER

cnt8:
	LEAQ 8(R14), CX
	CMPQ CX, R8
	JA   cnttail
	MOVQ (AX)(R14*1), CX
	XORQ (BX)(R14*1), CX
	JNE  cntdiff
	ADDQ $8, R14
	JMP  cnt8

cntdiff:
	BSFQ CX, CX
	SHRQ $3, CX
	ADDQ CX, R14
	JMP  cntdone

cnttail:
	CMPQ    R14, R8
	JAE     cntdone
	MOVBLZX (AX)(R14*1), CX
	MOVBLZX (BX)(R14*1), DI
	CMPL    CX, DI
	JNE     cntdone
	INCQ    R14
	JMP     cnttail

cntdone:
	CMPQ R14, R10
	JLE  cmp
	MOVQ R14, R10
	MOVL DX, R11
	CMPQ R14, R8
	JNE  cmp

done:
	MOVQ R10, AX
	MOVL $999999999, BX     // offBaseNotFound
	CMPQ R10, $3
	JLE  ret
	MOVL S_CURR, BX
	SUBL R11, BX
	ADDL $3, BX             // offsetToOffBase(curr - matchIndex)

ret:
	RET

bad:
	MOVQ $-1, AX
	RET

// func lazyRow66(p *rowAsmParams, seqs *seqDef, lits *byte, ip, anchor, iend, ilimit, prefixLowest int,
//	rep1, rep2 uint32, depth int) (ipOut, anchorOut, nSeq, nLits int, rep1Out, rep2Out, llType, llPos uint32)
//
// C: zstd_lazy.c:ZSTD_compressBlock_lazy_generic (noDict, row) for mls 6,
// rowLog 6: compressBlockLazyGeneric's match loop. R15 = p, SI = b.
// The repcodes live in the rep1/rep2 argument slots, the anchor and counts in
// their result slots. nSeq = -1 reports a table entry at or after the
// position searched (impossible).
TEXT ·lazyRow66(SB), NOSPLIT, $56-128
	MOVQ p+0(FP), R15
	MOVQ P_B, SI
	MOVQ ip+24(FP), AX
	MOVQ AX, L_IP
	MOVQ anchor+32(FP), AX
	MOVQ AX, anchorOut+88(FP)
	MOVQ $0, nSeq+96(FP)
	MOVQ $0, nLits+104(FP)
	MOVL $0, llType+120(FP)
	MOVL $0, llPos+124(FP)

main:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  finish
	MOVQ $0, L_MLEN
	MOVQ $1, L_OFFBASE      // repcode1ToOffBase
	LEAQ 1(R8), AX
	MOVQ AX, L_START

	// repcode at ip+1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   search0
	LEAQ  1(R8), AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, 1(SI)(R8*1)
	JNE   search0
	LEAQ  4(SI)(AX*1), R10
	LEAQ  5(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $5, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, L_MLEN
	CMPQ  depth+72(FP), $0
	JEQ   store

search0:
	MOVQ L_IP, DI
	CALL ·rowSearch66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, L_MLEN
	JLE  nobetter0
	MOVQ AX, L_MLEN
	MOVQ L_IP, CX
	MOVQ CX, L_START
	MOVQ BX, L_OFFBASE

nobetter0:
	CMPQ L_MLEN, $4
	JGE  found
	// no match: skip faster over incompressible data, maybe enter lazy skipping
	MOVQ L_IP, AX
	MOVQ AX, CX
	SUBQ anchorOut+88(FP), CX
	SARQ $8, CX              // kSearchStrength
	INCQ CX
	ADDQ CX, AX
	MOVQ AX, L_IP
	XORL DX, DX
	CMPQ CX, $8              // kLazySkippingStep
	SETHI DX
	MOVL DX, P_SKIP
	JMP  main

found:
	CMPQ depth+72(FP), $0
	JEQ  catchup

lazy:
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*3 > gain1 = mLen*3 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch1
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch1
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch1
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11            // mlRep
	LEAQ  (R11)(R11*2), AX   // gain2
	MOVQ  L_MLEN, CX
	LEAQ  (CX)(CX*2), CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX                 // gain1
	CMPQ  AX, CX
	JLE   lsearch1
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch1:
	MOVQ L_IP, DI
	CALL ·rowSearch66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  ldepth2
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 4
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $4, CX
	CMPQ DX, CX
	JLE  ldepth2
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

ldepth2:
	CMPQ depth+72(FP), $2
	JNE  catchup
	MOVQ L_IP, R8
	CMPQ R8, ilimit+48(FP)
	JGE  catchup
	INCQ R8
	MOVQ R8, L_IP
	// repcode at ip: gain2 = mlRep*4 > gain1 = mLen*4 - highbit(offBase) + 1
	MOVL  rep1+64(FP), DX
	TESTL DX, DX
	JEQ   lsearch2
	CMPQ  L_OFFBASE, $0
	JEQ   lsearch2
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   lsearch2
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	ADDQ  $4, R11
	MOVQ  R11, AX
	SHLQ  $2, AX
	MOVQ  L_MLEN, CX
	SHLQ  $2, CX
	BSRL  L_OFFBASE, DX
	SUBQ  DX, CX
	INCQ  CX
	CMPQ  AX, CX
	JLE   lsearch2
	MOVQ  R11, L_MLEN
	MOVQ  $1, L_OFFBASE
	MOVQ  L_IP, CX
	MOVQ  CX, L_START

lsearch2:
	MOVQ L_IP, DI
	CALL ·rowSearch66(SB)
	TESTQ AX, AX
	JLT  bad
	CMPQ AX, $4
	JLT  catchup
	// gain2 = ml2*4 - highbit(ofb) > gain1 = mLen*4 - highbit(offBase) + 7
	BSRL BX, CX
	MOVQ AX, DX
	SHLQ $2, DX
	SUBQ CX, DX
	MOVQ L_MLEN, CX
	SHLQ $2, CX
	BSRL L_OFFBASE, R8
	SUBQ R8, CX
	ADDQ $7, CX
	CMPQ DX, CX
	JLE  catchup
	MOVQ AX, L_MLEN
	MOVQ BX, L_OFFBASE
	MOVQ L_IP, CX
	MOVQ CX, L_START
	JMP  lazy

catchup:
	MOVQ L_OFFBASE, DX
	CMPQ DX, $3
	JLS  store              // a repcode: no catch up
	SUBQ $3, DX             // offset
	MOVQ L_START, R8
	MOVQ L_MLEN, AX

back:
	CMPQ    R8, anchorOut+88(FP)
	JLE     backdone
	MOVQ    R8, CX
	SUBQ    DX, CX
	CMPQ    CX, prefixLowest+56(FP)
	JLE     backdone
	MOVBLZX -1(SI)(R8*1), BX
	MOVBLZX -1(SI)(CX*1), R9
	CMPL    BX, R9
	JNE     backdone
	DECQ    R8
	INCQ    AX
	JMP     back

backdone:
	MOVQ R8, L_START
	MOVQ AX, L_MLEN
	MOVL rep1+64(FP), CX
	MOVL CX, rep2+68(FP)    // offset2 = offset1
	MOVL DX, rep1+64(FP)    // offset1 = offBase - REP_NUM

store:
	// storeSeq(start - anchor literals from anchor, offBase, mLen)
	MOVQ L_START, R9
	SUBQ anchorOut+88(FP), R9
	MOVQ L_OFFBASE, R12
	MOVQ L_MLEN, AX
	MOVQ $0, L_RET
	JMP  storeseq

afterstore:
	MOVQ L_START, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	CMPL P_SKIP, $0
	JEQ  reploop
	// leave lazy skipping: ZSTD_row_fillHashCache(ms, base, rowLog, mls, nextToUpdate, ilimit)
	MOVL $0, P_SKIP
	MOVQ P_NEXT, AX
	MOVL (AX), R8            // idx
	MOVL R8, AX
	SUBL P_BASEIDX, AX       // its position
	MOVQ ilimit+48(FP), BX
	SUBQ AX, BX
	JLT  reploop             // idx beyond ilimit: nothing to fill
	INCQ BX
	CMPQ BX, $8
	JLE  fillcnt
	MOVQ $8, BX

fillcnt:
	MOVQ P_CACHE, DX

fillloop:
	MOVL R8, AX
	SUBL P_BASEIDX, AX
	MOVQ (SI)(AX*1), R10
	MOVQ $0xcf1bbcdcbf9b0000, CX
	IMULQ CX, R10
	XORQ P_SALT, R10
	MOVQ P_HSHIFT, CX
	SHRQ CX, R10
	MOVL R10, R11
	SHRL $8, R11
	SHLL $6, R11
	MOVQ P_HASHTABLE, CX
	PREFETCHT0 (CX)(R11*4)
	PREFETCHT0 64(CX)(R11*4)
	ADDQ P_TAGTABLE, R11
	PREFETCHT0 (R11)
	PREFETCHT0 32(R11)
	MOVL R8, AX
	ANDL $7, AX
	MOVL R10, (DX)(AX*4)
	INCL R8
	DECQ BX
	JNE  fillloop

reploop:
	// while ip <= ilimit && offset2 > 0 && read32(ip) == read32(ip - offset2)
	MOVQ  L_IP, R8
	CMPQ  R8, ilimit+48(FP)
	JGT   main
	MOVL  rep2+68(FP), DX
	TESTL DX, DX
	JEQ   main
	MOVQ  R8, AX
	SUBQ  DX, AX
	MOVL  (SI)(AX*1), CX
	CMPL  CX, (SI)(R8*1)
	JNE   main
	LEAQ  4(SI)(AX*1), R10
	LEAQ  4(SI)(R8*1), R9
	MOVQ  iend+40(FP), R13
	SUBQ  R8, R13
	SUBQ  $4, R13
	CALL  ·fastCount(SB)
	LEAQ  4(R11), AX         // matchLength
	MOVL  rep2+68(FP), CX    // swap repcodes
	MOVL  rep1+64(FP), DX
	MOVL  DX, rep2+68(FP)
	MOVL  CX, rep1+64(FP)
	MOVQ  AX, L_MLEN
	XORL  R9, R9             // no literals
	MOVL  $1, R12            // repcode1ToOffBase
	MOVQ  $1, L_RET
	JMP   storeseq

afterrep:
	MOVQ L_IP, R8
	ADDQ L_MLEN, R8
	MOVQ R8, L_IP
	MOVQ R8, anchorOut+88(FP)
	JMP  reploop

	// storeseq: R9 litLen (from anchor), R12 offBase, AX matchLength;
	// returns to afterstore (L_RET = 0) or afterrep (L_RET = 1).
storeseq:
	TESTQ R9, R9
	JEQ   seq
	MOVQ  lits+16(FP), R10
	ADDQ  nLits+104(FP), R10
	MOVQ  anchorOut+88(FP), R11
	ADDQ  SI, R11
	CALL  ·fastCopyLits(SB)
	ADDQ  R9, nLits+104(FP)

seq:
	MOVQ seqs+8(FP), R10
	MOVQ nSeq+96(FP), R11
	MOVL R12, (R10)(R11*8)
	MOVW R9, 4(R10)(R11*8)
	LEAQ -3(AX), CX
	MOVW CX, 6(R10)(R11*8)
	CMPQ R9, $0xFFFF
	JLS  nolongll
	MOVL $1, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongll:
	CMPQ CX, $0xFFFF
	JLS  nolongml
	MOVL $2, llType+120(FP)
	MOVL R11, llPos+124(FP)

nolongml:
	INCQ R11
	MOVQ R11, nSeq+96(FP)
	CMPQ L_RET, $0
	JEQ  afterstore
	JMP  afterrep

finish:
	MOVQ L_IP, AX
	MOVQ AX, ipOut+80(FP)
	MOVL rep1+64(FP), AX
	MOVL AX, rep1Out+112(FP)
	MOVL rep2+68(FP), AX
	MOVL AX, rep2Out+116(FP)
	RET

bad:
	MOVQ $-1, nSeq+96(FP)
	RET

DATA rowMask15<>+0(SB)/4, $15
GLOBL rowMask15<>(SB), RODATA|NOPTR, $4
DATA rowMask31<>+0(SB)/4, $31
GLOBL rowMask31<>(SB), RODATA|NOPTR, $4
DATA rowMask63<>+0(SB)/4, $63
GLOBL rowMask63<>(SB), RODATA|NOPTR, $4
